model.variable('var1').set('gPE', ['xzpf*withsol(sol_o, comp1.ewfd.freq)*pi*epsilon0_const*sqrt(5.7)^4*comp1.diamond(' newline '2*withsol(sol_o, real(conj(comp1.ewfd.Ex)*comp1.ewfd.Ey))*p44*comp1.solid.eXY + 2*withsol(sol_o, real(conj(comp1.ewfd.Ex)*comp1.ewfd.Ez))*p44*comp1.solid.eXZ  + 2*withsol(sol_o, real(conj(comp1.ewfd.Ey)*comp1.ewfd.Ez))*p44*comp1.solid.eYZ +' newline 'withsol(sol_o, abs(comp1.ewfd.Ex)^2)*(p11*comp1.solid.eXX+p12*(comp1.solid.eYY+comp1.solid.eZZ))+ withsol(sol_o, abs(comp1.ewfd.Ey)^2)*(p11*comp1.solid.eYY+p12*(comp1.solid.eXX+comp1.solid.eZZ))+ withsol(sol_o, abs(comp1.ewfd.Ez)^2)*(p11*comp1.solid.eZZ+p12*(comp1.solid.eXX+comp1.solid.eYY)))/(LV*comp1.max(abs(comp1.solid.disp)))']);
model.variable('var1').set('gMB', 'xzpf*0.5*withsol(sol_o, comp1.ewfd.freq)*2*pi*LMB/(LV*comp1.max(abs(comp1.solid.disp)))');
model.variable('var1').set('xzpf', 'sqrt(hbar_const/(2*3515*meff*comp1.solid.omega))');
model.variable('var1').set('meff', 'comp1.diamond(comp1.solid.disp^2)/comp1.max(comp1.solid.disp^2)');
model.variable('var1').set('LMB', 'comp1.diamond_surface((u*nX+v*nY+w*nZ)*((5.7-1)*epsilon0_const*Epara-(1/5.7-1)/epsilon0_const*Dperp))');
model.variable('var1').set('LV', 'comp1.all(abs(withsol(sol_o, comp1.ewfd.normE))^2*withsol(sol_o, comp1.ewfd.epsrAv)*epsilon0_const)');
model.variable('var1').set('Epara', 'withsol(sol_o, abs(comp1.ewfd.normE)^2)-abs(nx*withsol(sol_o, comp1.ewfd.Ex)+ny*withsol(sol_o, comp1.ewfd.Ey)+nz*withsol(sol_o, comp1.ewfd.Ez))^2');
model.variable('var1').set('Dperp', 'abs(nx*withsol(sol_o,  comp1.ewfd.Dx))^2+abs(ny*withsol(sol_o, comp1.ewfd.Dy))^2+abs(nz*withsol(sol_o, comp1.ewfd.Dz))^2');

