% To import content from file, use:
% model.variable('var2').loadFile('FILENAME');
model.variable('var2').set('meff2', 'comp1.diamond(solid.disp^2)*3515');
model.variable('var2').set('zpf', 'sqrt(hbar_const/(2*comp1.solid.omega*meff2))');
model.variable('var2').set('exx', '1/6*comp1.solid.eXX+2/6*comp1.solid.eXY-4/6*comp1.solid.eXZ+comp1.solid.eYY-4/6*comp1.solid.eYZ+4/6*comp1.solid.eZZ');
model.variable('var2').set('eyy', '1/2*comp1.solid.eXX-comp1.solid.eXY+1/2*comp1.solid.eYY');
model.variable('var2').set('exy', 'sqrt(3)/6*(-comp1.solid.eXX+2*comp1.solid.eXZ+comp1.solid.eYY-2*comp1.solid.eYZ)');
model.variable('var2').set('ezx', 'sqrt(2)/6*(-comp1.solid.eXX+2*comp1.solid.eXY+comp1.solid.eXZ-comp1.solid.eYY+comp1.solid.eYZ+2*comp1.solid.eZZ)');
model.variable('var2').set('eyz', 'sqrt(6)/6*(comp1.solid.eXX+comp1.solid.eXZ-comp1.solid.eYY-comp1.solid.eYZ)');
model.variable('var2').set('Eg', 'sqrt(abs(dg*(exx-eyy)+fg*eyz)^2+abs(-2*i*dg*exy+i*fg*ezx)^2)');
model.variable('var2').set('dg', '1.3e15[Hz]*0.37');
model.variable('var2').set('fg', '-1.7e15[Hz]*0.37');
model.variable('var2').set('gsp', 'abs(Eg*zpf*sqrt(2)*comp1.solid.omega/(2*pi)/46e9)');

