model.variable('var1').set('LV', '4*comp1.all(abs(withsol(sol_o, comp1.ewfd.normE, setind(lambda, o_index)))^2*withsol(sol_o, comp1.ewfd.epsrAv, setind(lambda, o_index))*epsilon0_const)');

